static struct regmap * felix_request_regmap_by_name ( struct felix * felix , const char * resource_name ) { struct ocelot * ocelot = & felix -> ocelot ; struct resource res ; int i ; for ( i = 0 ; i < felix -> info -> num_resources ; i ++ ) { if ( strcmp ( resource_name , felix -> info -> resources [ i ] . name ) ) { continue ; } memcpy ( & res , & felix -> info -> resources [ i ] , sizeof ( res ) ) ; res . start += felix -> switch_base ; res . end += felix -> switch_base ; return ocelot_regmap_init ( ocelot , & res ) ; } return ERR_PTR ( - ENOENT ) ; } 